<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#111;font-size:12px}.row{display:flex;justify-content:space-between}.title{font-size:24px;font-weight:700}.muted{color:#666}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{padding:9px;border-bottom:1px solid #ddd;text-align:left}.right{text-align:right}.total{font-size:16px;font-weight:bold}</style></head><body><div class="row"><div><div class="title">AESTHETIC STORE</div><div class="muted">{{ config('store.email') }} · {{ config('store.phone') }}</div></div><div><b>INVOICE</b><br>{{ $order->order_number }}<br>{{ $order->created_at->format('d M Y') }}</div></div><hr><h3>Bill / Ship to</h3><p>{{ $order->customer_name }}<br>{{ $order->phone }}<br>{{ $order->address }}, {{ $order->area }}, {{ $order->district }}</p><table><thead><tr><th>Item</th><th>SKU</th><th>Qty</th><th class="right">Price</th><th class="right">Total</th></tr></thead><tbody>@foreach($order->items as $i)<tr><td>{{ $i->product_name }} {{ $i->variant_name ? '('.$i->variant_name.')':'' }}</td><td>{{ $i->sku }}</td><td>{{ $i->quantity }}</td><td class="right">{{ number_format($i->price,2) }}</td><td class="right">{{ number_format($i->line_total,2) }}</td></tr>@endforeach</tbody></table><p class="right">Subtotal: {{ number_format($order->subtotal,2) }}<br>Delivery: {{ number_format($order->delivery_charge,2) }}<br><span class="total">Total: {{ config('store.symbol') }}{{ number_format($order->total,2) }}</span></p><p>Payment: {{ strtoupper($order->payment_method) }} / {{ ucfirst($order->payment_status) }}</p></body></html>
